BEGIN;
ALTER TABLE public.redirect_workspace_members DROP CONSTRAINT redirect_workspace_members_pending_tenant_fence;
DO $$ DECLARE fence text; BEGIN
 SELECT conname INTO fence FROM pg_constraint WHERE conrelid='public.redirect_workspaces'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%status%provisioning%is_legacy%';
 IF fence IS NULL THEN RAISE EXCEPTION 'Missing activation fixture fence';END IF;
 EXECUTE format('ALTER TABLE public.redirect_workspaces DROP CONSTRAINT %I',fence);
END $$;
SET LOCAL ROLE service_role;
DO $$ DECLARE actor uuid:=gen_random_uuid();owner_id uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();first_workspace uuid:=gen_random_uuid();second_workspace uuid:=gen_random_uuid();member uuid;result jsonb; BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(owner_id),(outsider);
 INSERT INTO public.user_roles(user_id,role) VALUES(actor,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(first_workspace,'Owned private workspace','owned-private-workspace'),(second_workspace,'Member private workspace','member-private-workspace');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(first_workspace,actor),(second_workspace,owner_id);
 INSERT INTO public.redirect_workspace_members(workspace_id,user_id,kind,label,role) VALUES(second_workspace,actor,'user','Current billing','billing') RETURNING id INTO member;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor)::text,true);
 result:=public.redirect_account_workspaces(actor);
 IF(result->>'count')::int<>1 OR result->>'currentWorkspaceId'<>'58aa4340-8f21-4b7f-9a10-90be2da89c01' THEN RAISE EXCEPTION 'Provisioning workspace leaked into discovery';END IF;
 UPDATE public.redirect_workspaces SET status='active' WHERE id IN(first_workspace,second_workspace);
 result:=public.redirect_account_workspaces(actor,second_workspace);
 IF(result->>'count')::int<>3 OR result->>'currentWorkspaceId'<>second_workspace::text OR NOT result->'data' @> jsonb_build_array(jsonb_build_object('id',first_workspace,'role','owner')) OR NOT result->'data' @> jsonb_build_array(jsonb_build_object('id',second_workspace,'role','billing')) THEN RAISE EXCEPTION 'Current Owner/member discovery failed';END IF;
 IF public.redirect_account_workspaces(actor,outsider)->>'currentWorkspaceId' IS NOT NULL THEN RAISE EXCEPTION 'Unavailable explicit selection fell back';END IF;
 IF jsonb_array_length(public.redirect_account_workspaces(actor,NULL,100)->'data')<>0 OR(public.redirect_account_workspaces(actor,NULL,100)->>'count')::int<>3 THEN RAISE EXCEPTION 'Workspace offset boundary failed';END IF;
 UPDATE public.redirect_workspace_members SET active=false WHERE id=member;
 IF(public.redirect_account_workspaces(actor)->>'count')::int<>2 THEN RAISE EXCEPTION 'Stale inactive membership discovered';END IF;
 UPDATE redirect_internal.workspace_owners SET active=false WHERE workspace_id=first_workspace;
 IF(public.redirect_account_workspaces(actor)->>'count')::int<>1 THEN RAISE EXCEPTION 'Global admin inherited future workspace ownership';END IF;
 BEGIN PERFORM public.redirect_account_workspaces(owner_id);RAISE EXCEPTION 'Actor substitution accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',outsider)::text,true);
 result:=public.redirect_account_workspaces(outsider);
 IF(result->>'count')::int<>0 OR result->>'currentWorkspaceId' IS NOT NULL THEN RAISE EXCEPTION 'No-access account discovery failed';END IF;
 BEGIN PERFORM public.redirect_account_workspaces(outsider,NULL,-1);RAISE EXCEPTION 'Invalid offset accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor)::text,true);
 INSERT INTO public.redirect_workspaces(name,slug) SELECT 'Paging workspace '||n,'catalog-page-'||n FROM generate_series(1,101) n;
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) SELECT id,actor FROM public.redirect_workspaces WHERE slug LIKE 'catalog-page-%';
 UPDATE public.redirect_workspaces SET status='active' WHERE slug LIKE 'catalog-page-%';
 result:=public.redirect_account_workspaces(actor);
 IF(result->>'count')::int<>102 OR(result->>'nextOffset')::int<>100 OR jsonb_array_length(result->'data')<>100 OR jsonb_array_length(public.redirect_account_workspaces(actor,NULL,100)->'data')<>2 OR public.redirect_account_workspaces(actor,NULL,100)->>'nextOffset' IS NOT NULL THEN RAISE EXCEPTION 'Workspace pagination lost or duplicated visible identities';END IF;
 IF has_function_privilege('anon','public.redirect_account_workspaces(uuid,uuid,integer)','execute') OR has_function_privilege('authenticated','public.redirect_account_workspaces(uuid,uuid,integer)','execute') THEN RAISE EXCEPTION 'Account discovery exposed outside service';END IF;
END $$;
ROLLBACK;
